"use client";

import * as React from "react";
import { cn } from "../../lib/utils.js";

interface DropzoneProps
	extends Omit<
		React.HTMLAttributes<HTMLDivElement>,
		"onChange" | "onDrop" | "children"
	> {
	/** Fired with the accepted file list every time the user picks or drops files. */
	onFilesSelected?: (files: File[]) => void;
	/**
	 * Fired when files are dropped/picked but ALL of them are filtered out by
	 * `accept` / `maxSize` / `maxFiles`. Useful for surfacing "file too large"
	 * or "wrong type" toasts to the user. Receives the rejected File[].
	 */
	onFilesRejected?: (files: File[]) => void;
	/** `accept` attribute forwarded to the hidden file input (e.g. "image/*", ".csv"). */
	accept?: string;
	/** Allow multiple files. Default true. */
	multiple?: boolean;
	/** Maximum total file count (after dedupe). Excess files are dropped silently — surface in your handler. */
	maxFiles?: number;
	/** Maximum size per file in bytes. Files over the cap are filtered before onFilesSelected fires. */
	maxSize?: number;
	/** Disable interaction. */
	disabled?: boolean;
	/** Optional render override for the dropzone body. Receives drag state. */
	children?: React.ReactNode | ((state: DropzoneRenderState) => React.ReactNode);
	/** Required accessible name for the drop area. */
	"aria-label": string;
}

interface DropzoneRenderState {
	isDragOver: boolean;
	isDisabled: boolean;
	openFileDialog: () => void;
}

/** Apply `accept` / `maxSize` / `maxFiles` filters before emitting to onFilesSelected. */
function filterFiles(
	files: FileList | File[],
	{ accept, maxSize, maxFiles }: { accept?: string; maxSize?: number; maxFiles?: number },
): File[] {
	const list = Array.from(files);
	const acceptList = accept
		? accept
				.split(",")
				.map((s) => s.trim())
				.filter(Boolean)
		: undefined;

	const matchAccept = (file: File): boolean => {
		if (!acceptList) return true;
		return acceptList.some((entry) => {
			if (entry.startsWith(".")) {
				return file.name.toLowerCase().endsWith(entry.toLowerCase());
			}
			if (entry.endsWith("/*")) {
				const prefix = entry.slice(0, -1); // "image/"
				return file.type.startsWith(prefix);
			}
			return file.type === entry;
		});
	};

	const sized =
		typeof maxSize === "number" ? list.filter((f) => f.size <= maxSize) : list;
	const accepted = sized.filter(matchAccept);
	if (typeof maxFiles === "number") return accepted.slice(0, maxFiles);
	return accepted;
}

/**
 * Drag-and-drop file input built on the native HTML5 drag-drop API plus a
 * visually-hidden (sr-only) `<input type="file">` for screen-reader and
 * keyboard access.
 *
 * Two interaction surfaces:
 * - The visible drop area is a `role="button"` div with `tabIndex=0` and the
 *   required `aria-label`. Click, Enter, or Space proxies through to click the
 *   hidden input, opening the system file dialog.
 * - The hidden input itself remains in the accessibility tree (sr-only, NOT
 *   `aria-hidden`) so AT-driven file pickers can find it directly.
 *
 * Pass `children` as a node (default placeholder) or a function receiving
 * `{ isDragOver, isDisabled, openFileDialog }` for full layout control.
 * @returns A drop area + hidden file input pair that yields a File[].
 */
function Dropzone({
	onFilesSelected,
	onFilesRejected,
	accept,
	multiple = true,
	maxFiles,
	maxSize,
	disabled = false,
	children,
	className,
	"aria-label": ariaLabel,
	...rest
}: DropzoneProps) {
	const inputRef = React.useRef<HTMLInputElement>(null);
	const [isDragOver, setIsDragOver] = React.useState(false);
	const dragCounter = React.useRef(0);

	const emit = React.useCallback(
		(files: FileList | File[] | null | undefined) => {
			if (!files || disabled) return;
			const all = Array.from(files);
			if (all.length === 0) return;
			const accepted = filterFiles(all, { accept, maxSize, maxFiles });
			if (accepted.length === 0) {
				onFilesRejected?.(all);
				return;
			}
			const finalAccepted = !multiple ? accepted.slice(0, 1) : accepted;
			const rejected = all.filter((f) => !finalAccepted.includes(f));
			onFilesSelected?.(finalAccepted);
			if (rejected.length > 0) onFilesRejected?.(rejected);
		},
		[
			accept,
			disabled,
			maxFiles,
			maxSize,
			multiple,
			onFilesSelected,
			onFilesRejected,
		],
	);

	/*
	 * Reset the drag counter + isDragOver when the user cancels a drag outside
	 * the dropzone (Esc, drag off the page, switch tab). Without this, the
	 * counter can stay >0 and the dropzone gets stuck in its hover style.
	 */
	React.useEffect(() => {
		const reset = () => {
			dragCounter.current = 0;
			setIsDragOver(false);
		};
		window.addEventListener("dragend", reset);
		window.addEventListener("drop", reset);
		return () => {
			window.removeEventListener("dragend", reset);
			window.removeEventListener("drop", reset);
		};
	}, []);

	const openFileDialog = React.useCallback(() => {
		if (disabled) return;
		inputRef.current?.click();
	}, [disabled]);

	const handleDragEnter = (e: React.DragEvent<HTMLDivElement>) => {
		if (disabled) return;
		e.preventDefault();
		dragCounter.current += 1;
		if (e.dataTransfer.types.includes("Files")) setIsDragOver(true);
	};
	const handleDragOver = (e: React.DragEvent<HTMLDivElement>) => {
		if (disabled) return;
		e.preventDefault();
		e.dataTransfer.dropEffect = "copy";
	};
	const handleDragLeave = (e: React.DragEvent<HTMLDivElement>) => {
		if (disabled) return;
		e.preventDefault();
		dragCounter.current = Math.max(0, dragCounter.current - 1);
		if (dragCounter.current === 0) setIsDragOver(false);
	};
	const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
		if (disabled) return;
		e.preventDefault();
		dragCounter.current = 0;
		setIsDragOver(false);
		emit(e.dataTransfer.files);
	};
	const handleKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
		if (disabled) return;
		if (e.key === "Enter" || e.key === " ") {
			e.preventDefault();
			openFileDialog();
		}
	};

	const renderState: DropzoneRenderState = {
		isDragOver,
		isDisabled: disabled,
		openFileDialog,
	};

	return (
		<>
			<div
				role="button"
				tabIndex={disabled ? -1 : 0}
				aria-label={ariaLabel}
				aria-disabled={disabled || undefined}
				data-drag-over={isDragOver || undefined}
				onClick={openFileDialog}
				onKeyDown={handleKeyDown}
				onDragEnter={handleDragEnter}
				onDragOver={handleDragOver}
				onDragLeave={handleDragLeave}
				onDrop={handleDrop}
				className={cn(
					"flex w-full cursor-pointer select-none flex-col items-center justify-center gap-[var(--space-2,0.5rem)] rounded-md border-2 border-dashed border-input bg-background px-[var(--space-6,1.5rem)] py-[var(--space-8,2rem)] text-center text-sm transition-all duration-[var(--duration-normal,200ms)] ease-out",
					"hover:bg-accent hover:text-accent-foreground",
					"focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
					isDragOver && "border-primary bg-accent text-accent-foreground",
					disabled && "pointer-events-none opacity-50",
					className,
				)}
				{...rest}
			>
				{typeof children === "function"
					? children(renderState)
					: (children ?? (
							<>
								<svg
									xmlns="http://www.w3.org/2000/svg"
									viewBox="0 0 24 24"
									fill="none"
									stroke="currentColor"
									strokeWidth="2"
									strokeLinecap="round"
									strokeLinejoin="round"
									className="h-6 w-6 text-muted-foreground"
									aria-hidden="true"
								>
									<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
									<polyline points="17 8 12 3 7 8" />
									<line x1="12" y1="3" x2="12" y2="15" />
								</svg>
								<span className="font-medium">
									{isDragOver ? "Drop files to upload" : "Drag files here or click to browse"}
								</span>
								{accept ? (
									<span className="text-xs text-muted-foreground">{accept}</span>
								) : null}
							</>
						))}
			</div>
			{/*
			 * Input lives OUTSIDE the role="button" container to satisfy axe
			 * nested-interactive. It is aria-hidden (outer button is the AT
			 * surface) and clicked programmatically via inputRef.current?.click().
			 */}
			<input
				ref={inputRef}
				type="file"
				accept={accept}
				multiple={multiple}
				disabled={disabled}
				aria-hidden="true"
				tabIndex={-1}
				className="sr-only"
				onChange={(e) => {
					emit(e.target.files);
					// Reset so picking the same file twice still fires onChange
					e.target.value = "";
				}}
			/>
		</>
	);
}
Dropzone.displayName = "Dropzone";

export { Dropzone };
export type { DropzoneProps, DropzoneRenderState };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex UI: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

